{
  "hypothesis": "The Principle of Inherited Source-Operator Covariance (PISO) posits that the physical field configuration $\tilde{\rho}$ is not generated de novo from P1, but is the unitary transport of the declared operational seed state $\rho_{seed}$ by a specific geometric automorphism $U_{geo}$ derived from the double cover structure and compiler constraints. Specifically, if the source kernel P1 defines a boundary condition on an oriented seam with unit winding, and the double cover provides a canonical lift of the coordinate symmetry group to the spinor bundle, then the physical field moments must satisfy $\tilde{\rho} = U_{geo} \rho_{seed} U_{geo}^\top$. This principle replaces the assumption that P1 alone dictates the specific vacuum sector or time-evolution operator, instead treating the 'compiler' (the mapping from algebraic source to physical readout) as the active agent that selects the physical realization via this covariance. It explicitly bridges the gap between the abstract P1 kernel and the concrete QFT007/QFT008 results by asserting that the OS/CAR net is a covariant image of the seed, not an independent derivation.",
  "source_ids": [
    "finding:original-p1-is-structured-kernel-and-not-c3-alone",
    "finding:original-common-action-os-and-1pi-chain-already-exists",
    "finding:actual-fold-native-sigma-generates-marked-source-spinor-and-minimal-charge-closure"
  ],
  "premises": [
    "premise:declared-p1-p2",
    "premise:typed-source-structures",
    "premise:original-p1-seed-boundary-and-local-restriction-definitions",
    "premise:actual-full-v252-unimodular-p2-gauge-lift"
  ],
  "additional_assumptions": [
    "The 'compiler' is defined as the specific unitary map $U_{geo}$ that aligns the native clock/charge marking of the double cover with the physical readout slots, a step not guaranteed by P1 alone.",
    "The operational seed $\rho_{seed}$ contains the necessary topological data (omega, ten-tuple) but lacks the dynamical selection mechanism for the physical vacuum without the covariance map.",
    "The optional CAR clock route is strictly local and does not impose global constraints on the source kernel's structural integrity."
  ],
  "tests": [
    "quillen-relative-normalization",
    "theta-heat-shape-response",
    "doubled-source-counting"
  ],
  "proposed_predictions": [
    {
      "check_id": "quillen-relative-normalization",
      "claim_id": "normalized_zero_source_has_shape_response",
      "expects": true
    },
    {
      "check_id": "theta-heat-shape-response",
      "claim_id": "charge_curvature_fixes_theta_shape_derivative",
      "expects": true
    },
    {
      "check_id": "doubled-source-counting",
      "claim_id": "two_quarter_blocks_are_two_faces",
      "expects": false
    }
  ]
}

